<body>
    <div class="container">
        <h1>2048</h1>
        <div class="info-bar">
            <div class="score-container">
                <div class="score-label">Score</div>
                <div id="score">0</div>
            </div>
            <button id="reset">New Game</button>
        </div>
        <div id="board"></div>
        <div class="instructions">
            <p>Use arrow keys to move tiles</p>
            <p>Combine tiles to reach 2048!</p>
        </div>
    </div>

    <script>
        class Game2048 {
            constructor() {
                this.size = 4;
                this._board = [];
                this._score = 0;
                this.init();
            }

            init() {
                this._board = Array(this.size * this.size).fill(0);
                this._score = 0;
                this.spawnTile();
                this.spawnTile();
                this.render();
            }

            reset() {
                this.init();
            }

            board() {
                return this._board.slice();
            }

            setBoard(arr) {
                this._board = arr.slice();
                this.render();
            }

            score() {
                return this._score;
            }

            spawnTile() {
                const empty = [];
                for (let i = 0; i < this._board.length; i++) {
                    if (this._board[i] === 0) {
                        empty.push(i);
                    }
                }

                if (empty.length === 0) return;

                const idx = empty[Math.floor(Math.random() * empty.length)];
                const value = Math.random() < 0.9 ? 2 : 4;
                this._board[idx] = value;

                // Mark as new for animation
                const tiles = document.querySelectorAll('.tile');
                if (tiles[idx]) {
                    tiles[idx].classList.add('new-tile');
                    setTimeout(() => tiles[idx].classList.remove('new-tile'), 150);
                }
            }

            move(direction) {
                const boardBefore = this._board.slice();
                const rows = this.size;
                const cols = this.size;

                if (direction === 'left') {
                    for (let r = 0; r < rows; r++) {
                        const row = [];
                        for (let c = 0; c < cols; c++) {
                            row.push(this._board[r * cols + c]);
                        }
                        const merged = this.mergeLine(row);
                        for (let c = 0; c < cols; c++) {
                            this._board[r * cols + c] = merged[c];
                        }
                    }
                } else if (direction === 'right') {
                    for (let r = 0; r < rows; r++) {
                        const row = [];
                        for (let c = 0; c < cols; c++) {
                            row.push(this._board[r * cols + c]);
                        }
                        const merged = this.mergeLine(row.reverse()).reverse();
                        for (let c = 0; c < cols; c++) {
                            this._board[r * cols + c] = merged[c];
                        }
                    }
                } else if (direction === 'up') {
                    for (let c = 0; c < cols; c++) {
                        const col = [];
                        for (let r = 0; r < rows; r++) {
                            col.push(this._board[r * cols + c]);
                        }
                        const merged = this.mergeLine(col);
                        for (let r = 0; r < rows; r++) {
                            this._board[r * cols + c] = merged[r];
                        }
                    }
                } else if (direction === 'down') {
                    for (let c = 0; c < cols; c++) {
                        const col = [];
                        for (let r = 0; r < rows; r++) {
                            col.push(this._board[r * cols + c]);
                        }
                        const merged = this.mergeLine(col.reverse()).reverse();
                        for (let r = 0; r < rows; r++) {
                            this._board[r * cols + c] = merged[r];
                        }
                    }
                }

                const changed = !this.arraysEqual(boardBefore, this._board);

                if (changed) {
                    this.spawnTile();
                    this.render();
                }

                return changed;
            }

            mergeLine(line) {
                // Remove zeros
                let nonZero = line.filter(x => x !== 0);

                // Merge adjacent equal values (left to right, each value merges at most once)
                const merged = [];
                const used = new Set();

                for (let i = 0; i < nonZero.length; i++) {
                    if (used.has(i)) continue;

                    let val = nonZero[i];

                    // Look for next non-merged value that equals this one
                    for (let j = i + 1; j < nonZero.length; j++) {
                        if (used.has(j)) continue;

                        if (nonZero[j] === val) {
                            val = val * 2;
                            this._score += val;
                            used.add(j);
                            break;
                        } else {
                            break;
                        }
                    }

                    merged.push(val);
                }

                // Pad with zeros to original size
                while (merged.length < line.length) {
                    merged.push(0);
                }

                return merged;
            }

            arraysEqual(a, b) {
                if (a.length !== b.length) return false;
                for (let i = 0; i < a.length; i++) {
                    if (a[i] !== b[i]) return false;
                }
                return true;
            }

            render() {
                const boardEl = document.getElementById('board');
                boardEl.innerHTML = '';

                for (let i = 0; i < this._board.length; i++) {
                    const tile = document.createElement('div');
                    tile.className = 'tile';
                    const value = this._board[i];

                    if (value === 0) {
                        tile.classList.add('empty');
                    } else {
                        tile.setAttribute('data-value', value);
                        tile.textContent = value;
                    }

                    boardEl.appendChild(tile);
                }

                document.getElementById('score').textContent = this._score;
            }
        }

        // Global game instance
        const gameInstance = new Game2048();

        // Expose API
        window.game = {
            size: 4,
            reset: () => gameInstance.reset(),
            move: (direction) => gameInstance.move(direction),
            board: () => gameInstance.board(),
            setBoard: (arr) => gameInstance.setBoard(arr),
            score: () => gameInstance.score(),
        };

        // Reset button
        document.getElementById('reset').addEventListener('click', () => {
            gameInstance.reset();
        });

        // Arrow key controls
        document.addEventListener('keydown', (e) => {
            const dirMap = {
                'ArrowLeft': 'left',
                'ArrowRight': 'right',
                'ArrowUp': 'up',
                'ArrowDown': 'down',
            };

            const direction = dirMap[e.key];
            if (direction) {
                e.preventDefault();
                gameInstance.move(direction);
            }
        });
    </script>
</body>
</html>
